{re:/data\/hubmap\/learn_qing\.webp/,D:{k:"lrn_qing",nm:"清・江南書院",it:[
  {n:"磚雕門樓",s:[[[225,985],[260,930],[300,905],[470,905],[515,930],[555,985],[510,1000],[508,1268],[465,1268],[465,1102],[310,1102],[310,1268],[270,1268],[270,1000]]],
   t:"大門是淡青灰色的磚雕門樓，匾額的地方空著。蘇州網師園乾隆年間的「藻耀高翔」門樓，就是江南磚雕門樓的代表。"},
  {n:"圓燈籠",s:[[167,557,17],[297,557,17],[474,557,17],[604,557,17],[13,537,14],[755,537,14],[96,464,13],[672,464,13],[167,396,12],[604,396,12],[294,227,11],[474,227,11]],
   t:"屋簷下掛的是圓圓的素紗燈籠。你在新手訓練營每上完一課，這 12 盞燈就由近到遠多亮一盞。"},
  {n:"書院講堂",s:[[[130,505],[200,425],[560,425],[640,505],[620,530],[610,648],[160,648],[150,530]]],
   t:"清代江南有不少有名的書院。像蘇州的紫陽書院，就是康熙五十二年（1713 年）設立的；南京也有雍正元年（1723 年）設立的鍾山書院。"},
  {n:"漏窗",s:[[[30,470],[70,455],[70,525],[30,540]],[[80,445],[112,432],[112,482],[80,494]],[[658,448],[690,450],[690,490],[658,488]],[[700,476],[732,480],[732,527],[700,523]]],
   t:"長廊白牆上開著鏤空花格的小窗，叫「漏窗」。灰磚門樓、漏窗、鼓凳、蓋碗，都是這座清代江南書院的特色。"},
  {n:"前院老樹",s:[[[640,950],[700,925],[768,935],[768,1205],[738,1205],[722,1110],[700,1060],[660,1040],[640,1000]]],
   t:"前院老樹下是新手訓練營的沙盤，四周擺著圓鼓鼓的鼓凳。清代王再越的《梅花譜》（康熙年間）是有名的象棋古譜。"},
  {n:"藏書閣旁的古松",s:[[[135,240],[200,195],[260,205],[285,250],[262,300],[262,390],[230,390],[215,290],[150,280]],[[480,240],[530,210],[590,235],[592,270],[540,290],[525,375],[500,375],[505,280],[480,270]]],
   t:"藏書閣兩旁各有一株老松，枝幹彎彎曲曲。穿過講堂、走到最後面的藏書閣，就能去棋譜庫讀古譜。"}],
  no:[[[45,1025],[180,1025],[180,1220],[45,1220]],[[555,1072],[725,1072],[725,1215],[555,1215]],[[132,815],[238,815],[238,955],[132,955]],[[448,840],[628,840],[628,985],[448,985]],[[630,660],[768,580],[768,915],[630,800]],[[282,650],[492,650],[492,722],[282,722]],[[18,595],[132,595],[132,865],[18,865]],[[492,635],[640,635],[640,712],[492,712]],[[302,212],[466,212],[466,278],[302,278]],[[330,298],[438,298],[438,365],[330,365]]]}},
/* ⚔ 對戰頁 秦・酒肆（park/hubmap/考究說明_各朝對戰_1109.md）：夯土院牆、黑瓦黑漆、青銅吊燈盞、坐榻矮几；天井 no 縮成矮榻本身，四周坐榻可點 */
{re:/data\/hubmap\/battle(_red|_curtain)?_qin\.webp/,D:{k:"bt_qin",nm:"秦・酒肆",it:[
  {n:"酒肆的雅座",s:[[[0,430],[165,425],[165,505],[0,512]]],
   t:"秦朝還沒有茶樓，所以這裡畫成賣酒的酒肆，兼做客舍。《韓非子》記戰國時宋國有個賣酒的人「懸幟甚高」，把酒旗掛得高高的招客，可見戰國就有掛旗招客的酒肆。"},
  {n:"夯土院牆",s:[[[440,255],[768,250],[768,395],[596,395],[596,345],[505,345],[500,320],[440,300]]],
   t:"右上這道院牆是黃土一層層夯實的夯土牆，刷成土黃色，牆頂平直，只蓋一道瓦簷。{{ming:一階一階高起的馬頭牆是明朝中期以後徽州的房子才有的，秦朝沒有。}}"},
  {n:"黑瓦和黑漆木構",s:[[[0,232],[355,212],[480,222],[500,330],[0,338]]],
   t:"屋頂鋪著灰黑色的筒瓦，簷口是素面的圓瓦當，柱子、門板漆成深黑色。秦朝崇尚黑色，{{han:《史記》說秦朝}}{{<han:規定}}「衣服旄旌節旗皆上黑」，所以連牌匾也用黑漆。"},
  {n:"青銅燈盞",s:[[23,424,18],[175,410,18],[499,356,16],[204,586,17],[392,540,16],[699,892,18]],
   t:"屋簷下用細鏈吊著小小的青銅燈盞，秦朝照明用的是青銅燈。平常不點火；等千秋盃開始比賽、說書台垂下大幕，這些燈才會亮起來。"},
  {n:"坐榻和矮几",s:[[[305,697],[362,697],[364,724],[305,726]],[[448,702],[505,702],[512,742],[455,744]],[[272,775],[340,770],[350,812],[278,818]],[[412,792],[485,788],[492,828],[418,832]],[[250,555],[330,555],[330,600],[250,600]]],
   t:"天井那張寬矮的木榻四周，擺著四張鋪蒲席的小坐榻；樓上樓下也都是矮几和坐席。秦人席地而坐，家具是案、几、席{{song:，高桌高椅要到唐宋才普及}}。"},
  {n:"天邊的星槎",s:[[678,212,32]],
   t:"遠遠的雲上有一艘小帆船，那就是雲河星槎，跟首頁河上停的、星槎頁你搭的是同一艘船。"}],
  no:[[[296,724],[395,686],[490,726],[486,782],[378,818],[298,772]],[[18,775],[305,775],[305,1185],[18,1185]],[[548,395],[768,395],[768,770],[548,770]],[[205,320],[425,320],[425,505],[205,505]],[[428,820],[690,820],[690,1125],[428,1125]],[[505,345],[596,345],[596,525],[505,525]]]}},
/* ⚔ 對戰頁 漢・酒肆（park/hubmap/考究說明_各朝對戰_1109.md）：陶樓樣式木樓、漆耳杯酒尊、夯土院牆、青銅吊燈盞、坐榻 */
{re:/data\/hubmap\/battle(_red|_curtain)?_han\.webp/,D:{k:"bt_han",nm:"漢・酒肆",it:[
  {n:"漆耳杯和酒尊",s:[[[0,430],[165,425],[165,505],[0,512]]],
   t:"二樓這張矮案上，擺著紅黑兩色的漆耳杯和酒尊。漢代人喝酒用漆耳杯，例如馬王堆漢墓出土的「君幸酒」漆耳杯；圖上的杯子是素面的，沒有字。"},
  {n:"陶樓樣式的酒樓",s:[[[90,508],[420,505],[420,640],[300,650],[180,650],[90,590]]],
   t:"這座兩層的酒樓，是照漢代陶樓明器的樣子畫的：夯土牆、木柱、灰筒瓦、直櫺窗，二樓圍著直櫺欄杆。漢代已經有兩三層的木構樓閣，各地漢墓出土了很多這種陶樓。"},
  {n:"夯土院牆",s:[[[440,255],[768,250],[768,395],[596,395],[596,345],[505,345],[500,320],[440,300]]],
   t:"右上這道夯土院牆，牆頂平直，只蓋一道瓦簷，牆後露出兩坡灰瓦屋頂。{{ming:一階一階高起的馬頭牆是明朝中期以後才有的，漢朝沒有。}}"},
  {n:"青銅燈盞",s:[[23,424,18],[175,410,18],[499,356,16],[204,586,17],[392,540,16],[699,892,18]],
   t:"屋簷下用細鏈吊著小小的青銅燈盞。漢代的燈多半放在案上或燈架上，這裡把燈吊在簷下，是為了配合千秋盃點燈。平常不點火；等千秋盃開始比賽、說書台垂下大幕，這些燈才會亮起來。"},
  {n:"坐榻",s:[[[305,697],[362,697],[364,724],[305,726]],[[448,702],[505,702],[512,742],[455,744]],[[272,775],[340,770],[350,812],[278,818]],[[412,792],[485,788],[492,828],[418,832]],[[250,555],[330,555],[330,600],[250,600]]],
   t:"天井那張矮榻四周，擺著四張鋪蒲席的小坐榻，一樓、左下房間也是矮几和坐席。漢人席地而坐{{song:，高桌高椅要到唐宋才普及}}。"},
  {n:"天邊的星槎",s:[[678,212,32]],
   t:"遠遠的雲上有一艘小帆船，那就是雲河星槎，跟首頁河上停的、星槎頁你搭的是同一艘船。"}],
  no:[[[296,724],[395,686],[490,726],[486,782],[378,818],[298,772]],[[18,775],[305,775],[305,1185],[18,1185]],[[548,395],[768,395],[768,770],[548,770]],[[205,320],[425,320],[425,505],[205,505]],[[428,820],[690,820],[690,1125],[428,1125]],[[505,345],[596,345],[596,525],[505,525]]]}},
/* ⚔ 對戰頁 三國・酒肆（park/hubmap/考究說明_各朝對戰_1109.md）：青瓷罐、青瓷盆、黃泥夯土院牆、吊燈盞、坐榻 */
{re:/data\/hubmap\/battle(_red|_curtain)?_sanguo\.webp/,D:{k:"bt_sg",nm:"三國・酒肆",it:[
  {n:"青瓷罐",s:[[[0,430],[165,425],[165,505],[0,512]],[[250,555],[330,555],[330,600],[250,600]]],
   t:"二樓和一樓矮几上青綠色的罐子是青瓷。孫吳的時候，越窯青瓷大量流行，南京、紹興一帶的吳墓出土了很多。"},
  {n:"門前的青瓷盆",s:[[[410,1085],[505,1085],[505,1195],[410,1195]],[[690,915],[760,915],[760,1062],[690,1062]]],
   t:"門前這幾個青綠釉的盆是青瓷盆，種著蘭草和梅枝。三國孫吳時青瓷已經很流行{{yuan:；成熟的青花瓷要到元朝才燒成，所以這裡不用青花盆}}。"},
  {n:"黃泥夯土院牆",s:[[[440,255],[768,250],[768,395],[596,395],[596,345],[505,345],[500,320],[440,300]]],
   t:"右上這道黃泥夯土牆，牆頂平直，只蓋一道瓦簷。{{ming:一階一階高起的馬頭牆是明朝中期以後徽州的房子才有的，三國時還沒有。}}"},
  {n:"吊燈盞",s:[[23,424,18],[175,410,18],[499,356,16],[204,586,17],[392,540,16],[699,892,18]],
   t:"屋簷下用細鏈吊著小小的燈盞，平常不點火；等千秋盃開始比賽、說書台垂下大幕，這些燈才會亮起來。"},
  {n:"坐榻和矮几",s:[[[305,697],[362,697],[364,724],[305,726]],[[448,702],[505,702],[512,742],[455,744]],[[272,775],[340,770],[350,812],[278,818]],[[412,792],[485,788],[492,828],[418,832]]],
   t:"天井那張矮榻四周，擺著四張小坐榻。三國時仍是席地而坐，用矮几、坐席和矮榻{{song:，高桌高椅要到唐宋才普及}}。"},
  {n:"天邊的星槎",s:[[678,212,32]],
   t:"遠遠的雲上有一艘小帆船，那就是雲河星槎，跟首頁河上停的、星槎頁你搭的是同一艘船。"}],
  no:[[[296,724],[395,686],[490,726],[486,782],[378,818],[298,772]],[[18,775],[305,775],[305,1185],[18,1185]],[[548,395],[768,395],[768,770],[548,770]],[[205,320],[425,320],[425,505],[205,505]],[[428,820],[690,820],[690,1125],[428,1125]],[[505,345],[596,345],[596,525],[505,525]]]}},
/* ⚔ 對戰頁 魏晉・酒壚（park/hubmap/考究說明_各朝對戰_1109.md）：竹叢、青瓷吊燈、白粉院牆、酒壚雅座、青瓷盆、坐榻 */
{re:/data\/hubmap\/battle(_red|_curtain)?_weijin\.webp/,D:{k:"bt_wj",nm:"魏晉・酒壚",it:[
  {n:"酒壚的雅座",s:[[[0,430],[165,425],[165,505],[0,512]]],
   t:"魏晉這一站畫成「酒壚」，就是賣酒的小店。{{nanbei:《世說新語》記}}王戎經過黃公酒壚，想起當年和嵇康、阮籍在這裡一起喝酒。"},
  {n:"竹叢",s:[[[372,505],[430,505],[445,560],[440,605],[375,605]],[[305,840],[385,840],[385,940],[305,940]],[[112,572],[195,572],[195,668],[112,668]]],
   t:"天井和樓梯邊種了幾叢竹子。{{nanbei:《世說新語》記}}王子猷借住別人的空房子，也要馬上種竹，說「何可一日無此君」，意思是怎麼可以一天沒有竹子。"},
  {n:"青瓷吊燈",s:[[23,424,18],[175,410,18],[499,356,16],[204,586,17],[392,540,16],[699,892,18],[358,1060,18]],
   t:"屋簷下用細鏈吊著淺碗形的青瓷燈盞，平常不點火；等千秋盃開始比賽、說書台垂下大幕，這些燈才會亮起來。"},
  {n:"白粉院牆",s:[[[440,255],[768,250],[768,395],[596,395],[596,345],[505,345],[500,320],[440,300]]],
   t:"右上這道白粉牆，牆頂是平的，只蓋一道瓦簷{{ming:，不是一階一階的馬頭牆}}。用白灰粉刷牆面，漢魏時就已經有了。"},
  {n:"門前的青瓷盆",s:[[[378,1085],[505,1085],[505,1190],[378,1190]]],
   t:"門前種蘭草的盆是青綠色的青瓷。兩晉的越窯青瓷很盛行，雞首壺就是那時候的代表器形。"},
  {n:"坐榻",s:[[[305,697],[362,697],[364,724],[305,726]],[[448,702],[505,702],[512,742],[455,744]],[[272,775],[340,770],[350,812],[278,818]],[[412,792],[485,788],[492,828],[418,832]]],
   t:"天井那張矮榻四周，擺著四張小坐榻。魏晉時仍是席地而坐，用憑几、坐席和矮榻{{song:，高桌高椅要到唐宋才普及}}。"},
  {n:"天邊的星槎",s:[[678,212,32]],
   t:"遠遠的雲上有一艘小帆船，那就是雲河星槎，跟首頁河上停的、星槎頁你搭的是同一艘船。"}],
  no:[[[296,724],[395,686],[490,726],[486,782],[378,818],[298,772]],[[18,775],[305,775],[305,1185],[18,1185]],[[548,395],[768,395],[768,770],[548,770]],[[205,320],[425,320],[425,505],[205,505]],[[428,820],[690,820],[690,1125],[428,1125]],[[505,345],[596,345],[596,525],[505,525]]]}},
/* ⚔ 對戰頁 南北朝・酒肆（park/hubmap/考究說明_各朝對戰_1109.md）：青瓷酒尊、白粉院牆、青瓷吊燈、坐榻 */
{re:/data\/hubmap\/battle(_red|_curtain)?_nanbei\.webp/,D:{k:"bt_nb",nm:"南北朝・酒肆",it:[
  {n:"青瓷酒尊",s:[[[0,430],[165,425],[165,505],[0,512]]],
   t:"二樓矮案上放著青瓷的酒尊和碗。{{tang:杜牧的詩說「水村山郭酒旗風，南朝四百八十寺」，南朝江南的村子和城邊，到處看得到招客的酒旗。}}"},
  {n:"白粉院牆",s:[[[440,255],[768,250],[768,395],[596,395],[596,345],[505,345],[500,320],[440,300]]],
   t:"右上這道白粉牆，牆頂是平的，只蓋一道瓦簷{{ming:，不是一階一階的馬頭牆}}。用白灰粉刷牆面，漢魏時就已經有了。"},
  {n:"青瓷吊燈",s:[[23,424,18],[175,410,18],[499,356,16],[204,586,17],[392,540,16],[699,892,18]],
   t:"屋簷下用細鏈吊著淺碗形的青瓷燈盞，平常不點火；等千秋盃開始比賽、說書台垂下大幕，這些燈才會亮起來。"},
  {n:"坐榻",s:[[[305,697],[362,697],[364,724],[305,726]],[[448,702],[505,702],[512,742],[455,744]],[[272,775],[340,770],[350,812],[278,818]],[[412,792],[485,788],[492,828],[418,832]],[[250,555],[330,555],[330,600],[250,600]]],
   t:"天井那張矮榻四周，擺著四張小坐榻。南北朝時坐具開始變高，但還是以席和榻為主，所以樓上樓下都是矮几和坐席。"},
  {n:"天邊的星槎",s:[[678,212,32]],
   t:"遠遠的雲上有一艘小帆船，那就是雲河星槎，跟首頁河上停的、星槎頁你搭的是同一艘船。"}],
  no:[[[296,724],[395,686],[490,726],[486,782],[378,818],[298,772]],[[18,775],[305,775],[305,1185],[18,1185]],[[548,395],[768,395],[768,770],[548,770]],[[205,320],[425,320],[425,505],[205,505]],[[428,820],[690,820],[690,1125],[428,1125]],[[505,345],[596,345],[596,525],[505,525]]]}},
/* ⚔ 對戰頁 隋・酒肆（park/hubmap/考究說明_各朝對戰_1109.md）：坊牆、盤口壺、吊燈盞、坐榻、青瓷盆 */
{re:/data\/hubmap\/battle(_red|_curtain)?_sui\.webp/,D:{k:"bt_sui",nm:"隋・酒肆",it:[
  {n:"盤口壺",s:[[[0,430],[165,425],[165,505],[0,512]]],
   t:"二樓桌上這種口沿像小盤子的壺，叫盤口壺，有白瓷也有青瓷。河南安陽的隋朝張盛墓（595 年）出土過白瓷，是早期白瓷的代表。"},
  {n:"坊牆",s:[[[440,255],[768,250],[768,395],[596,395],[596,345],[505,345],[500,320],[440,300]]],
   t:"右上這道牆頂平直的白粉牆是坊牆。隋朝的都城大興城採用里坊制，所以這裡畫成平直的坊牆{{ming:，不畫一階一階的馬頭牆}}。"},
  {n:"吊燈盞",s:[[23,424,18],[175,410,18],[499,356,16],[204,586,17],[392,540,16],[699,892,18]],
   t:"屋簷下用細鏈吊著小小的燈盞，平常不點火；等千秋盃開始比賽、說書台垂下大幕，這些燈才會亮起來。"},
  {n:"坐榻",s:[[[305,697],[362,697],[364,724],[305,726]],[[448,702],[505,702],[512,742],[455,744]],[[272,775],[340,770],[350,812],[278,818]],[[412,792],[485,788],[492,828],[418,832]]],
   t:"天井那張矮榻四周，擺著四張小坐榻。隋代仍以席和榻為主{{song:，高桌高椅要到唐宋才普及}}。"},
  {n:"門前的青瓷盆",s:[[[338,1145],[440,1145],[440,1240],[338,1240]],[[458,1105],[505,1105],[505,1190],[458,1190]],[[690,985],[730,985],[730,1055],[690,1055]]],
   t:"門前的盆景種在青綠色的青瓷盆裡。{{yuan:成熟的青花瓷要到元朝才燒成，隋朝還沒有，所以這裡不用青花盆。}}"},
  {n:"天邊的星槎",s:[[678,212,32]],
   t:"遠遠的雲上有一艘小帆船，那就是雲河星槎，跟首頁河上停的、星槎頁你搭的是同一艘船。"}],
  no:[[[296,724],[395,686],[490,726],[486,782],[378,818],[298,772]],[[18,775],[305,775],[305,1185],[18,1185]],[[548,395],[768,395],[768,770],[548,770]],[[205,320],[425,320],[425,505],[205,505]],[[428,820],[690,820],[690,1125],[428,1125]],[[505,345],[596,345],[596,525],[505,525]]]}},
/* ⚔ 對戰頁 唐・旗亭（park/hubmap/考究說明_各朝對戰_1109.md）：鴟尾、白紗燈籠、煎茶器、盆松、旗亭、平直院牆 */
{re:/data\/hubmap\/battle(_red|_curtain)?_tang\.webp/,D:{k:"bt_tang",nm:"唐・旗亭",it:[
  {n:"煎茶器具",s:[[[0,430],[165,425],[165,505],[0,512]]],
   t:"二樓這張桌上擺著小風爐、茶鍑（小鐵鍋）和茶碗，是照陸羽《茶經》畫的煎茶器具。封演《封氏聞見記》說開元以後，城裡「多開店鋪，煎茶賣之」，所以這座旗亭也兼賣茶。"},
  {n:"旗亭",s:[[[90,508],[420,505],[420,640],[300,650],[180,650],[90,590]]],
   t:"唐代的「旗亭」就是酒樓。薛用弱《集異記》記王昌齡、高適、王之渙在旗亭聽伶人唱詩，比誰的詩被唱得多，這就是「旗亭畫壁」的故事。"},
  {n:"鴟尾",s:[[[402,182],[452,182],[452,242],[402,242]]],
   t:"大屋頂正脊的盡頭翹起一個大大的裝飾，叫「鴟尾」。朱柱白壁、灰瓦、正脊鴟尾、簷下斗栱，就是這座唐代旗亭的樣子。"},
  {n:"白紗燈籠",s:[[24,418,21],[174,400,21],[500,352,19],[204,584,21],[391,537,19],[697,890,21]],
   t:"屋簷下掛著竹骨白紗燈籠，唐代的上元燈節已經很熱鬧。燈籠平常不點火；等千秋盃開始比賽、說書台垂下大幕，才會亮起來。"},
  {n:"門前盆松",s:[[[340,1065],[505,1065],[505,1200],[340,1200]],[[692,905],[768,905],[768,1055],[692,1055]]],
   t:"門前的盆裡種著小松樹，做成盆景。唐朝章懷太子墓（706 年）的壁畫上，就有侍女捧著盆景。"},
  {n:"平直的院牆",s:[[[440,255],[768,250],[768,395],[596,395],[596,345],[505,345],[500,320],[440,300]]],
   t:"右上這道白牆牆頂平直，只蓋一道瓦簷。{{ming:一階一階高起的馬頭牆是明朝中期以後徽州的房子才有的，唐朝沒有。}}"},
  {n:"天邊的星槎",s:[[678,212,32]],
   t:"遠遠的雲上有一艘小帆船，那就是雲河星槎，跟首頁河上停的、星槎頁你搭的是同一艘船。"}],
  no:[[[278,690],[502,690],[502,855],[278,855]],[[18,775],[305,775],[305,1185],[18,1185]],[[548,395],[768,395],[768,770],[548,770]],[[205,320],[425,320],[425,505],[205,505]],[[428,820],[690,820],[690,1125],[428,1125]],[[505,345],[596,345],[596,525],[505,525]]]}},
/* ⚔ 對戰頁 五代・茶肆（park/hubmap/考究說明_各朝對戰_1109.md）：黑漆高桌靠背椅、紙燈籠、淡黃泥牆 */
{re:/data\/hubmap\/battle(_red|_curtain)?_wudai\.webp/,D:{k:"bt_wd",nm:"五代・茶肆",it:[
  {n:"黑漆高桌和靠背椅",s:[[[0,430],[165,425],[165,505],[0,512]],[[250,555],[330,555],[330,600],[250,600]]],
   t:"樓上這張黑漆高桌配著靠背椅，是照顧閎中〈韓熙載夜宴圖〉{{song:（今天看到的是宋代摹本）}}裡五代江南士大夫的家具畫的。五代時垂足坐已經普遍，可以用高桌、靠背椅和長凳。"},
  {n:"素色紙燈籠",s:[[24,418,21],[174,400,21],[500,352,19],[204,584,21],[391,537,19],[697,890,21]],
   t:"屋簷下掛著素色的紙燈籠，唐末五代已經可以用紙燈籠。燈籠平常不點火；等千秋盃開始比賽、說書台垂下大幕，才會亮起來。"},
  {n:"門邊的青瓷瓶",s:[[[684,935],[768,935],[768,1070],[684,1070]]],
   t:"大門右邊立著一個青綠色的青瓷瓶，旁邊的長方盆也是青瓷的顏色。五代越窯的青瓷，有「秘色瓷」的名稱。"},
  {n:"淡黃泥牆",s:[[[440,255],[768,250],[768,395],[596,395],[596,345],[505,345],[500,320],[440,300]]],
   t:"右上這道淡黃色的泥牆，牆頂平直，只蓋一道瓦簷。{{ming:一階一階高起的馬頭牆是明朝中期以後才有的，五代還沒有。}}"},
  {n:"天邊的星槎",s:[[678,212,32]],
   t:"遠遠的雲上有一艘小帆船，那就是雲河星槎，跟首頁河上停的、星槎頁你搭的是同一艘船。"}],
  no:[[[278,690],[502,690],[502,855],[278,855]],[[18,775],[305,775],[305,1185],[18,1185]],[[548,395],[768,395],[768,770],[548,770]],[[205,320],[425,320],[425,505],[205,505]],[[428,820],[690,820],[690,1125],[428,1125]],[[505,345],[596,345],[596,525],[505,525]]]}},
/* ⚔ 對戰頁 宋・茶坊（park/hubmap/考究說明_各朝對戰_1109.md）：山水立軸、燈掛椅、龍泉青瓷盆、紅紙燈籠、白粉院牆 */
{re:/data\/hubmap\/battle(_red|_curtain)?_song\.webp/,D:{k:"bt_song",nm:"宋・茶坊",it:[
  {n:"山水立軸",s:[[[438,343],[474,343],[474,424],[438,424]]],
   t:"二樓牆上掛著一幅山水立軸。宋朝汴京、臨安都有很多茶坊，吳自牧《夢粱錄》說茶肆裡「插四時花，掛名人畫」，用花和畫招待客人。"},
  {n:"燈掛椅",s:[[[98,440],[134,440],[134,492],[98,492]],[[425,385],[446,385],[446,432],[425,432]]],
   t:"二樓這種靠背椅，椅背頂上的橫木兩端伸出來，叫「燈掛椅」。宋畫裡就看得到，例如〈清明上河圖〉、〈韓熙載夜宴圖〉的宋摹本。"},
  {n:"龍泉青瓷盆",s:[[[450,1127],[502,1127],[502,1195],[450,1195]],[[686,1015],[724,1015],[724,1080],[686,1080]],[[722,960],[768,960],[768,1028],[722,1028]]],
   t:"大門兩邊這幾個淡青色的盆（兩個圓盆、右邊一個長方盆），是龍泉青瓷。{{yuan:成熟的青花瓷要到元朝才燒成，所以}}宋朝這一站門前用的是龍泉窯那種粉青色的盆。"},
  {n:"紅紙燈籠",s:[[24,418,21],[174,400,21],[500,352,19],[204,584,21],[391,537,19],[697,890,21]],
   t:"屋簷下掛著圓圓的紅紙燈籠，平常不點火；等千秋盃開始比賽、說書台垂下大幕，這些燈籠才會亮起來。"},
  {n:"白粉院牆",s:[[[440,255],[768,250],[768,395],[596,395],[596,345],[505,345],[500,320],[440,300]]],
   t:"右上這道白牆牆頂平直，只蓋一道瓦簷，牆後露出灰瓦屋頂。{{ming:一階一階高起的馬頭牆是明朝中期以後徽州的房子才有的，宋朝沒有。}}"},
  {n:"天邊的星槎",s:[[678,212,32]],
   t:"遠遠的雲上有一艘小帆船，那就是雲河星槎，跟首頁河上停的、星槎頁你搭的是同一艘船。"}],
  no:[[[278,690],[502,690],[502,855],[278,855]],[[18,775],[305,775],[305,1185],[18,1185]],[[548,395],[768,395],[768,770],[548,770]],[[205,320],[425,320],[425,505],[205,505]],[[428,820],[690,820],[690,1125],[428,1125]],[[505,345],[596,345],[596,525],[505,525]]]}},
/* ⚔ 對戰頁 元・茶肆（park/hubmap/考究說明_各朝對戰_1109.md）：銅湯瓶茶碗、元青花盆、院牆與江南木屋、紅紙燈籠 */
{re:/data\/hubmap\/battle(_red|_curtain)?_yuan\.webp/,D:{k:"bt_yuan",nm:"元・茶肆",it:[
  {n:"銅湯瓶和茶碗",s:[[[0,430],[165,425],[165,505],[0,512]]],
   t:"二樓桌上是一把銅湯瓶，配著白瓷和青花的茶碗。元代點茶和散茶兩種喝法都有。"},
  {n:"元青花盆",s:[[[440,1126],[502,1126],[502,1192],[440,1192]],[[688,1010],[724,1010],[724,1076],[688,1076]]],
   t:"門前的花盆是青花瓷，畫著纏枝花紋。景德鎮在元代燒成成熟的青花，英國大維德基金會收藏的至正十一年青花雲龍象耳瓶，就是有名的例子。"},
  {n:"院牆和江南木屋",s:[[[440,255],[768,250],[768,395],[596,395],[596,345],[505,345],[500,320],[440,300]]],
   t:"右上這道白牆牆頂平直，牆後露出幾座木構外露的江南木屋。{{ming:一階一階高起的馬頭牆是明朝中期以後才有的，元朝還沒有。}}"},
  {n:"紅紙燈籠",s:[[24,418,21],[174,400,21],[500,352,19],[204,584,21],[391,537,19],[697,890,21]],
   t:"屋簷下掛著圓圓的紅紙燈籠，平常不點火；等千秋盃開始比賽、說書台垂下大幕，這些燈籠才會亮起來。"},
  {n:"天邊的星槎",s:[[678,212,32]],
   t:"遠遠的雲上有一艘小帆船，那就是雲河星槎，跟首頁河上停的、星槎頁你搭的是同一艘船。"}],
  no:[[[278,690],[502,690],[502,855],[278,855]],[[18,775],[305,775],[305,1185],[18,1185]],[[548,395],[768,395],[768,770],[548,770]],[[205,320],[425,320],[425,505],[205,505]],[[428,820],[690,820],[690,1125],[428,1125]],[[505,345],[596,345],[596,525],[505,525]]]}},
/* ⚔ 對戰頁 清・茶館（park/hubmap/考究說明_各朝對戰_1109.md）：馬頭牆（沿用原圖多邊形）、蓋碗紫砂、青花盆、紅紙燈籠 */
{re:/data\/hubmap\/battle(_red|_curtain)?_qing\.webp/,D:{k:"bt_qing",nm:"清・茶館",it:[
  {n:"蓋碗和紫砂壺",s:[[[0,430],[165,425],[165,505],[0,512]]],
   t:"二樓桌上是青花蓋碗和紫砂壺。清代的茶館用蓋碗喝茶，宜興紫砂壺在明末清初成熟；蘇州、揚州的茶館還常兼做書場，有人說評話、唱彈詞，李斗的《揚州畫舫錄》就記了不少揚州的說書人。"},
  {n:"馬頭牆",s:[[[388,150],[505,150],[505,205],[485,260],[400,260],[390,205]],[[485,215],[580,215],[580,262],[548,290],[488,262]],[[540,280],[700,300],[700,390],[540,355]],[[688,252],[768,252],[768,330],[692,320]]],
   t:"白牆頂上一階一階高起、蓋著黑瓦的牆，叫馬頭牆。它是明朝中期以後徽州的房子才有的，明清徽州、江南的民居都用，所以清朝這一站把它留著。"},
  {n:"青花盆",s:[[[440,1126],[502,1126],[502,1192],[440,1192]],[[688,1010],[724,1010],[724,1076],[688,1076]]],
   t:"門前的盆栽種在青花瓷盆裡。景德鎮在元代燒成成熟的青花，所以元朝以後的幾站，門前才看得到青花盆。"},
  {n:"紅紙燈籠",s:[[24,418,21],[174,400,21],[500,352,19],[204,584,21],[391,537,19],[697,890,21]],
   t:"屋簷下掛著圓圓的紅紙燈籠，平常不點火；等千秋盃開始比賽、說書台垂下大幕，這些燈籠才會亮起來。"},
  {n:"天邊的星槎",s:[[678,212,32]],
   t:"遠遠的雲上有一艘小帆船，那就是雲河星槎，跟首頁河上停的、星槎頁你搭的是同一艘船。"}],
  no:[[[278,690],[502,690],[502,855],[278,855]],[[18,775],[305,775],[305,1185],[18,1185]],[[548,395],[768,395],[768,770],[548,770]],[[205,320],[425,320],[425,505],[205,505]],[[428,820],[690,820],[690,1125],[428,1125]],[[505,345],[596,345],[596,525],[505,525]]]}},
/* 📜 秦・棋譜庫「丞相府圖籍室」（park/hubmap/考究說明_各朝學習棋譜_1109.md 秦・棋譜庫）。no 照原圖 lib；燈架已不是入口（回饋 846 拿掉搜尋），燈登記成物件，no 拿掉燈架那一塊 */
{re:/data\/libmap\/lib_qin\.webp/,D:{k:"lb_qin",nm:"秦・丞相府圖籍室",it:[
  {n:"竹簾窗",s:[[[520,222],[725,222],[725,358],[520,358]]],
   t:"二樓的窗扇往外推開，窗上捲起一片竹簾，看得到外面的天。這間圖籍室只用三種顏色：黑漆的櫃子和木箱、朱紅的封條、竹簡的黃。"},
  {n:"露明屋架",nh:1,s:[[[0,0],[768,0],[768,190],[500,150],[0,150]]],
   t:"這裡是秦朝丞相府收藏律令圖書的圖籍室。{{han:劉邦的軍隊打進咸陽時，蕭何搶先把秦丞相府、御史府的律令圖書收起來保存，《史記》記下了這件事。}}"},
  {n:"黑漆長案",s:[[[64,1082],[300,1078],[300,1240],[50,1250]],[[50,1250],[722,1238],[716,1376],[64,1376]]],
   t:"最前面這張黑漆長案，邊緣塗朱紅，案腳做成獸蹄的樣子。秦人其實用比較矮的案；這張是入口和迷你棋盤的位置，構圖固定，借用高案。案上攤開一幅空白素帛，旁邊是一捆捆竹簡。"},
  {n:"青銅豆形燈",s:[[[150,980],[250,980],[250,1040],[205,1048],[205,1125],[228,1135],[228,1165],[155,1165],[155,1135],[175,1125],[175,1048],[150,1040]]],
   t:"燈架上是一盞青銅豆形燈，樣子像一只有高腳的淺盤，盤裡盛油。秦朝的屋裡，就是用這種青銅燈照明。"},
  {n:"黑漆柱子",s:[[[214,560],[252,560],[252,895],[214,895]],[[530,600],[562,600],[562,960],[530,960]]],
   t:"一樓的柱子、書櫃和木箱都是深黑色。秦朝崇尚黑色，{{han:《史記》說秦朝}}{{<han:規定}}「衣服旄旌節旗皆上黑」，連衣服、旗子都用黑。"}],
  no:[[[0,648],[215,648],[215,1088],[0,1088]],[[538,700],[768,700],[768,1032],[538,1032]],[[0,192],[502,192],[502,425],[0,425]],[[500,368],[768,368],[768,452],[500,452]],[[302,1108],[476,1108],[476,1212],[302,1212]],[[528,1062],[692,1062],[692,1202],[528,1202]]]}},
/* 📜 漢・棋譜庫「石渠閣」（同上，漢・棋譜庫）。燈登記成物件，no 拿掉燈架 */
{re:/data\/libmap\/lib_han\.webp/,D:{k:"lb_han",nm:"漢・石渠閣",it:[
  {n:"露明屋架",nh:1,s:[[[0,0],[768,0],[768,190],[500,150],[0,150]]],
   t:"這裡是石渠閣，跟天祿閣一樣，是西漢皇家收藏圖書的地方。漢成帝時，劉向帶人校對、整理皇家收藏的經傳、諸子和詩賦。"},
  {n:"直櫺欄杆",s:[[[0,560],[230,448],[460,440],[460,470],[240,500],[0,612]],[[548,470],[768,486],[768,580],[548,560]]],
   t:"二樓走廊的欄杆是一根根直直的木條，{{song:比宋代一格一格的勾片欄杆樸素}}{{<song:樣子很樸素}}。欄杆後面牆上那 11 幅分格壁畫，取的是漢宣帝在麒麟閣畫霍光等十一位功臣像的故事。"},
  {n:"黑漆朱緣長案",s:[[[64,1082],[300,1078],[300,1240],[50,1250]],[[50,1250],[722,1238],[716,1376],[64,1376]]],
   t:"最前面這張黑漆長案鑲著朱紅的邊，是整間最搶眼的家具。漢代的案其實比較矮；這張是入口和迷你棋盤的位置，構圖固定，借用高案。案上攤開一幅空白素帛，右邊是一捆捆竹簡。"},
  {n:"青銅豆形燈",s:[[[150,980],[250,980],[250,1040],[205,1048],[205,1125],[228,1135],[228,1165],[155,1165],[155,1135],[175,1125],[175,1048],[150,1040]]],
   t:"燈架上是一盞青銅豆形燈，樣子像一只有高腳的淺盤，盤裡盛油。漢代的屋裡，就是用這種青銅燈照明。"},
  {n:"柱子和地磚",s:[[[214,560],[252,560],[252,895],[214,895]],[[530,600],[562,600],[562,960],[530,960]]],
   t:"一樓兩根素面木柱，撐起二樓的走廊。柱子腳下的方磚，印著一個個菱形的花紋。"}],
  no:[[[0,648],[215,648],[215,1088],[0,1088]],[[538,700],[768,700],[768,1032],[538,1032]],[[0,192],[502,192],[502,425],[0,425]],[[500,368],[768,368],[768,452],[500,452]],[[302,1108],[476,1108],[476,1212],[302,1212]],[[528,1062],[692,1062],[692,1202],[528,1202]]]}},
/* 📜 三國・棋譜庫「秘書監藏書閣」（同上，三國・棋譜庫）。燈登記成物件，no 拿掉燈架 */
{re:/data\/libmap\/lib_sanguo\.webp/,D:{k:"lb_sg",nm:"三國・秘書監藏書閣",it:[
  {n:"露明屋架",nh:1,s:[[[0,0],[768,0],[768,190],[500,150],[0,150]]],
   t:"曹魏設了「秘書監」，專門掌管國家的圖書，這裡就是秘書監的藏書閣。抬頭看，斜屋頂的木架直接露出來，沒有天花板遮住。"},
  {n:"欄杆和分格壁畫",s:[[[0,560],[230,448],[460,440],[460,470],[240,500],[0,612]],[[548,470],[768,486],[768,580],[548,560]]],
   t:"二樓的欄杆是一根根直木條。欄杆後面淺米色底的畫，是直接畫在白牆上、分成一格一格的「分格壁畫」，不是掛軸。"},
  {n:"長案和竹簡",s:[[[64,1082],[300,1078],[300,1240],[50,1250]],[[50,1250],[722,1238],[716,1376],[64,1376]]],
   t:"長案上堆著一捆捆竹簡，右邊還有一疊平放的木牘。1996 年長沙走馬樓出土了十多萬枚孫吳的簡牘，可見三國的官府文書還大量用竹簡和木牘。"},
  {n:"青瓷燈盞",s:[[[150,980],[250,980],[250,1040],[205,1048],[205,1125],[228,1135],[228,1165],[155,1165],[155,1135],[175,1125],[175,1048],[150,1040]]],
   t:"燈架上是一隻素面的青綠釉燈盞，是三國越窯的青瓷。東漢晚期浙江上虞已經燒出青瓷，到了孫吳時大量流行。"},
  {n:"柱子和柱礎",s:[[[214,560],[252,560],[252,895],[214,895]],[[530,600],[562,600],[562,960],[530,960]]],
   t:"一樓這兩根柱子是素面的褐色木頭，柱腳墊著一塊柱礎。三國這一站只用褐木、白牆和竹簡的黃，整間顏色淡雅。"}],
  no:[[[0,648],[215,648],[215,1088],[0,1088]],[[538,700],[768,700],[768,1032],[538,1032]],[[0,192],[502,192],[502,425],[0,425]],[[500,368],[768,368],[768,452],[500,452]],[[302,1108],[476,1108],[476,1212],[302,1212]],[[528,1062],[692,1062],[692,1202],[528,1202]]]}},
/* 📜 魏晉・棋譜庫「秘閣」（同上，魏晉・棋譜庫）。燈登記成物件，no 拿掉燈架 */
{re:/data\/libmap\/lib_weijin\.webp/,D:{k:"lb_wj",nm:"魏晉・秘閣",it:[
  {n:"露明屋架",nh:1,s:[[[0,0],[768,0],[768,190],[500,150],[0,150]]],
   t:"這裡是晉朝皇家藏書的秘閣。西晉的荀勖整理皇家藏書，編成《中經新簿》，把書分成甲、乙、丙、丁四部。"},
  {n:"直櫺欄杆和畫屏",s:[[[0,560],[230,448],[460,440],[460,470],[240,500],[0,612]],[[548,470],[768,486],[768,580],[548,560]]],
   t:"二樓的欄杆是一根根直木條。欄杆後面一排細黑框的畫屏，只用墨線白描人物，像顧愷之那一路的線描。"},
  {n:"長案和紙卷",s:[[[64,1082],[300,1078],[300,1240],[50,1250]],[[50,1250],[722,1238],[716,1376],[64,1376]]],
   t:"長案上攤開一張空白紙卷，右邊堆著一捆捆紙卷。東晉末年，桓玄下令官府「用簡的，都改用黃紙」，所以這一站的書以紙卷為主、竹簡為輔。"},
  {n:"青瓷燈盞",s:[[[150,980],[250,980],[250,1040],[205,1048],[205,1125],[228,1135],[228,1165],[155,1165],[155,1135],[175,1125],[175,1048],[150,1040]]],
   t:"燈架上是一隻素面的青瓷燈盞。兩晉的越窯青瓷很盛行，雞首壺就是那時候的代表器形。"},
  {n:"柱子和柱礎",s:[[[214,560],[252,560],[252,895],[214,895]],[[530,600],[562,600],[562,960],[530,960]]],
   t:"一樓兩根褐色木柱，撐起二樓的走廊。這一站只有褐木、白牆和書帙的竹黃色，看起來清清淡淡。"}],
  no:[[[0,648],[215,648],[215,1088],[0,1088]],[[538,700],[768,700],[768,1032],[538,1032]],[[0,192],[502,192],[502,425],[0,425]],[[500,368],[768,368],[768,452],[500,452]],[[302,1108],[476,1108],[476,1212],[302,1212]],[[528,1062],[692,1062],[692,1202],[528,1202]]]}},
/* 📜 南北朝・棋譜庫「文德殿書閣」（同上，南北朝・棋譜庫）。燈登記成物件，no 拿掉燈架 */
{re:/data\/libmap\/lib_nanbei\.webp/,D:{k:"lb_nb",nm:"南北朝・文德殿書閣",it:[
  {n:"露明屋架",nh:1,s:[[[0,0],[768,0],[768,190],[500,150],[0,150]]],
   t:"這裡叫文德殿書閣：南朝梁朝初年，在宮中的文德殿收藏了大批圖書{{tang:（《隋書·經籍志》）}}。抬頭看，斜屋頂的木架直接露出來，沒有天花板遮住。"},
  {n:"勾片欄杆和畫屏",s:[[[0,560],[230,448],[460,440],[460,470],[240,500],[0,612]],[[548,470],[768,486],[768,580],[548,560]]],
   t:"二樓欄杆是一格一格的勾片花紋。欄杆後面那排深色框的畫屏，根據的是北魏司馬金龍墓（484 年）出土的木板漆畫屏風，一塊塊畫板上畫著古人。"},
  {n:"朱紅柱子",s:[[[214,560],[252,560],[252,895],[214,895]],[[530,600],[562,600],[562,960],[530,960]]],
   t:"一樓的柱子漆成朱紅色，書櫃門也是朱漆。配上竹黃色的紙卷，整間顏色穩重。"},
  {n:"蓮瓣青瓷燈盞",s:[[[150,980],[250,980],[250,1040],[205,1048],[205,1125],[228,1135],[228,1165],[155,1165],[155,1135],[175,1125],[175,1048],[150,1040]]],
   t:"燈架上是一隻青瓷燈盞，盞口做成一片片蓮花瓣。蓮瓣花紋，跟南北朝時佛教盛行有關。"},
  {n:"長案和紙卷",s:[[[64,1082],[300,1078],[300,1240],[50,1250]],[[50,1250],[722,1238],[716,1376],[64,1376]]],
   t:"長案上攤開一張空白紙卷，右邊堆著一卷卷紙卷。{{tang:唐朝以前的}}{{<tang:這時候的}}書，大多是竹簡、帛書或捲起來的紙卷軸，書櫃裡的紙卷還用書帙包著。"},
  {n:"鎮尺",s:[[[278,1112],[300,1115],[288,1205],[266,1202]],[[474,1110],[494,1110],[508,1196],[486,1198]]],
   t:"攤開的紙卷兩邊，各壓著一根長條的「鎮尺」，把紙壓平，是書桌上常見的文具。"}],
  no:[[[0,648],[215,648],[215,1088],[0,1088]],[[538,700],[768,700],[768,1032],[538,1032]],[[0,192],[502,192],[502,425],[0,425]],[[500,368],[768,368],[768,452],[500,452]],[[302,1108],[476,1108],[476,1212],[302,1212]],[[528,1062],[692,1062],[692,1202],[528,1202]]]}},
/* 📜 隋・棋譜庫「觀文殿書閣」（同上，隋・棋譜庫）。燈登記成物件，no 拿掉燈架 */
{re:/data\/libmap\/lib_sui\.webp/,D:{k:"lb_sui",nm:"隋・觀文殿書閣",it:[
  {n:"斗栱屋架",nh:1,s:[[[0,0],[768,0],[768,190],[500,150],[0,150]]],
   t:"抬頭看，屋架上有一朵朵斗栱，還有斜斜撐著的「叉手」，看起來最像宮殿裡的殿閣。這裡是隋煬帝在東都觀文殿收藏圖書的書閣。"},
  {n:"長案和卷軸",s:[[[64,1082],[300,1078],[300,1240],[50,1250]],[[50,1250],[722,1238],[716,1376],[64,1376]]],
   t:"案上那堆卷軸，軸頭有紅、紺青、黑三種顏色。{{tang:《隋書·經籍志》說，}}隋煬帝把秘閣的書抄成五十份副本，分三品：上品用紅琉璃軸，中品用紺琉璃軸，下品用漆軸。"},
  {n:"蓮瓣青瓷燈盞",s:[[[150,980],[250,980],[250,1040],[205,1048],[205,1125],[228,1135],[228,1165],[155,1165],[155,1135],[175,1125],[175,1048],[150,1040]]],
   t:"燈架上是一隻青瓷燈盞，盞口做成一片片蓮花瓣。隋代的青瓷，常見這種蓮瓣花紋。"},
  {n:"勾片欄杆",s:[[[0,560],[230,448],[460,440],[460,470],[240,500],[0,612]],[[548,470],[768,486],[768,580],[548,560]]],
   t:"二樓欄杆是一格一格的勾片花紋。欄杆後面那排畫板上畫著古人，點了就是「特級大師」。"},
  {n:"鎮尺",s:[[[278,1112],[300,1115],[288,1205],[266,1202]],[[474,1110],[494,1110],[508,1196],[486,1198]]],
   t:"攤開的紙卷兩邊，各壓著一根長條的「鎮尺」，把紙壓平，是書桌上常見的文具。"}],
  no:[[[0,648],[215,648],[215,1088],[0,1088]],[[538,700],[768,700],[768,1032],[538,1032]],[[0,192],[502,192],[502,425],[0,425]],[[500,368],[768,368],[768,452],[500,452]],[[302,1108],[476,1108],[476,1212],[302,1212]],[[528,1062],[692,1062],[692,1202],[528,1202]]]}},
/* 📜 唐・棋譜庫「集賢殿書院」（同上，唐・棋譜庫）。燈登記成物件，no 拿掉燈架；鎮尺位置跟原圖不同，另量 */
{re:/data\/libmap\/lib_tang\.webp/,D:{k:"lb_tang",nm:"唐・集賢殿書院",it:[
  {n:"斗栱屋架",nh:1,s:[[[0,0],[768,0],[768,190],[500,150],[0,150]]],
   t:"朱紅的屋架上有斗栱和斜撐的叉手。唐玄宗開元十三年（725），把麗正修書院改名為集賢殿書院，「書院」這個名字就是從這裡開始的；不過那時的書院是皇家藏書、校書的地方，不是講學的學校。"},
  {n:"牙籤卷軸",s:[[[530,1055],[680,1055],[700,1130],[700,1242],[555,1242],[530,1200]]],
   t:"案上這堆卷軸包著彩色的書帙，每一卷都掛著一片小牌子，叫「牙籤」。韓愈寫別人家藏書「插架三萬軸，一一懸牙籤」，說的就是唐代這種卷軸書。"},
  {n:"蓮瓣柱礎",s:[[[214,560],[256,560],[258,912],[212,912]],[[530,600],[562,600],[562,964],[528,964]]],
   t:"柱子腳下墊著的柱礎，刻成一圈蓮花瓣。地上的方磚也印著寶相花紋，是這十一朝裡最繽紛的一間書閣。"},
  {n:"白瓷油盞",s:[[[150,980],[250,980],[250,1040],[205,1048],[205,1125],[228,1135],[228,1165],[155,1165],[155,1135],[175,1125],[175,1048],[150,1040]]],
   t:"燈架上是一隻白瓷油盞，盞裡搭著一根燈芯，沒有點火。唐代這一站的書閣，連燈也換成了白瓷。"},
  {n:"勾片欄杆",s:[[[0,560],[230,448],[460,440],[460,470],[240,500],[0,612]],[[548,470],[768,486],[768,580],[548,560]]],
   t:"二樓欄杆是一格一格的勾片花紋。欄杆後面那排畫像，取的是唐太宗貞觀十七年（643 年）在凌煙閣畫二十四位功臣像的意思，那些功臣像是閻立本畫的。"},
  {n:"鎮尺",s:[[[262,1112],[284,1112],[274,1205],[252,1203]],[[486,1110],[506,1110],[514,1202],[494,1204]]],
   t:"攤開的紙卷兩邊，各壓著一根長條的「鎮尺」，把紙壓平，是書桌上常見的文具。"}],
  no:[[[0,648],[215,648],[215,1088],[0,1088]],[[538,700],[768,700],[768,1032],[538,1032]],[[0,192],[502,192],[502,425],[0,425]],[[500,368],[768,368],[768,452],[500,452]],[[302,1108],[476,1108],[476,1212],[302,1212]],[[528,1062],[692,1062],[692,1202],[528,1202]]]}},
/* 📜 五代・棋譜庫「澄心堂書閣」（同上，五代・棋譜庫）。燈盞考究說明沒寫史實，不登記，no 照原圖（含燈架） */
{re:/data\/libmap\/lib_wudai\.webp/,D:{k:"lb_wd",nm:"五代・澄心堂書閣",it:[
  {n:"露明屋架",nh:1,s:[[[0,0],[768,0],[768,190],[500,150],[0,150]]],
   t:"澄心堂是南唐宮中的殿堂，後主李煜時在這裡收藏書畫、監製紙張，做出來的「澄心堂紙」{{song:，北宋的歐陽修、梅堯臣都很珍惜}}{{<song:，就是用這座殿堂的名字命名的}}。抬頭看，斜屋頂的木架直接露出來，沒有天花板遮住。"},
  {n:"勾片欄杆和畫障",s:[[[0,560],[230,448],[460,440],[460,470],[240,500],[0,612]],[[548,470],[768,486],[768,580],[548,560]]],
   t:"二樓欄杆是一格一格的勾片花紋。後面那排細木框的畫障，取的是南唐周文矩〈重屏會棋圖〉的意思：畫裡李璟兄弟圍著棋盤對坐，背後的屏風裡又畫著一座屏風。"},
  {n:"長案和冊子",s:[[[64,1082],[300,1078],[300,1240],[50,1250]],[[50,1250],[722,1238],[716,1376],[64,1376]]],
   t:"長案上攤開的是一本冊子，右邊疊著幾本書和一卷卷軸。五代的書還是以卷軸為主，但已經開始有經摺裝和冊子。"},
  {n:"鎮尺",s:[[[278,1112],[300,1115],[288,1205],[266,1202]],[[474,1110],[494,1110],[508,1196],[486,1198]]],
   t:"攤開的冊子兩邊，各壓著一根長條的「鎮尺」，把書頁壓平，是書桌上常見的文具。"},
  {n:"柱子和柱礎",s:[[[214,560],[252,560],[252,895],[214,895]],[[530,600],[562,600],[562,960],[530,960]]],
   t:"一樓兩根素面木柱，柱腳墊著柱礎。{{song:五代這一站的書閣，是十一朝裡跟宋代樣子最接近的一間。}}"}],
  no:[[[0,648],[215,648],[215,1088],[0,1088]],[[538,700],[768,700],[768,1032],[538,1032]],[[0,192],[502,192],[502,425],[0,425]],[[500,368],[768,368],[768,452],[500,452]],[[302,1108],[476,1108],[476,1212],[302,1212]],[[528,1062],[692,1062],[692,1202],[528,1202]],[[152,915],[228,915],[228,1168],[152,1168]]]}},
/* 📜 元・棋譜庫「書院藏書樓」（同上，元・棋譜庫；青花取同一份元・學習的文化段）。燈盞不登記，no 照原圖（含燈架） */
{re:/data\/libmap\/lib_yuan\.webp/,D:{k:"lb_yuan",nm:"元・書院藏書樓",it:[
  {n:"露明屋架",nh:1,s:[[[0,0],[768,0],[768,190],[500,150],[0,150]]],
   t:"這是元代書院的藏書樓。元代的建築延續宋代的做法，所以屋架、柱子都跟宋代的書閣很像。"},
  {n:"青花小罐",s:[[[242,1056],[288,1056],[294,1088],[288,1122],[244,1122],[236,1088]]],
   t:"桌角這隻白底藍花的小罐是青花瓷。景德鎮在元代燒成成熟的青花，例如英國大維德基金會收藏的至正十一年青花雲龍象耳瓶；在這座書院藏書樓裡，青花是到元朝才第一次出現。"},
  {n:"勾片欄杆",s:[[[0,560],[230,448],[460,440],[460,470],[240,500],[0,612]],[[548,470],[768,486],[768,580],[548,560]]],
   t:"二樓的欄杆是一格一格的勾片花紋，跟宋代的書閣一樣。元代的建築延續宋代的做法{{qing:；到了明、清兩站，欄杆才換成卍字紋和回紋}}。"},
  {n:"長案和冊子",s:[[[64,1082],[300,1078],[300,1240],[50,1250]],[[50,1250],[722,1238],[716,1376],[64,1376]]],
   t:"長案上攤開一本冊子，右邊和木櫥裡疊著素黃、素褐書衣的冊子。元代的書已經不是卷軸，而是平放疊起來的冊子；中國古書都是平放，不直立。"},
  {n:"鎮尺",s:[[[278,1112],[300,1115],[288,1205],[266,1202]],[[474,1110],[494,1110],[508,1196],[486,1198]]],
   t:"攤開的冊子兩邊，各壓著一根長條的「鎮尺」，把書頁壓平，是書桌上常見的文具。"}],
  no:[[[0,648],[215,648],[215,1088],[0,1088]],[[538,700],[768,700],[768,1032],[538,1032]],[[0,192],[502,192],[502,425],[0,425]],[[500,368],[768,368],[768,452],[500,452]],[[302,1108],[476,1108],[476,1212],[302,1212]],[[528,1062],[692,1062],[692,1202],[528,1202]],[[152,915],[228,915],[228,1168],[152,1168]]]}},
/* 📜 明・棋譜庫「天一閣」（同上，明・棋譜庫）。燈登記成物件，no 拿掉燈架 */
{re:/data\/libmap\/lib_ming\.webp/,D:{k:"lb_ming",nm:"明・天一閣",it:[
  {n:"露明屋架",nh:1,s:[[[0,0],[768,0],[768,190],[500,150],[0,150]]],
   t:"寧波的天一閣是明朝嘉靖年間范欽建的藏書樓，是中國現存最早的私家藏書樓。相傳取名「天一」，是取「天一生水」的意思，想用水來制火，保護藏書。"},
  {n:"長案和線裝書",s:[[[64,1082],[300,1078],[300,1240],[50,1250]],[[50,1250],[722,1238],[716,1376],[64,1376]]],
   t:"長案上和書櫥裡，是一疊疊平放的線裝書，書根朝外。線裝書在明代中後期普及，中國古書都是平放，不直立。"},
  {n:"卍字欄杆",s:[[[0,560],[230,448],[460,440],[460,470],[240,500],[0,612]],[[548,470],[768,486],[768,580],[548,560]]],
   t:"二樓的欄杆是一個個「卍」字連起來的花紋。北宋的《營造法式》裡，鉤闌就有「萬字」這一式。"},
  {n:"白瓷油盞",s:[[[150,980],[250,980],[250,1040],[205,1048],[205,1125],[228,1135],[228,1165],[155,1165],[155,1135],[175,1125],[175,1048],[150,1040]]],
   t:"燈架上放的是一隻白瓷油盞，盞裡盛油、搭上燈芯就能點燈。這一站的燈，用的是素淨的白瓷。"},
  {n:"鎮尺",s:[[[278,1112],[300,1115],[288,1205],[266,1202]],[[474,1110],[494,1110],[508,1196],[486,1198]]],
   t:"攤開的線裝書兩邊，各壓著一根長條的「鎮尺」，把書頁壓平，是書桌上常見的文具。"}],
  no:[[[0,648],[215,648],[215,1088],[0,1088]],[[538,700],[768,700],[768,1032],[538,1032]],[[0,192],[502,192],[502,425],[0,425]],[[500,368],[768,368],[768,452],[500,452]],[[302,1108],[476,1108],[476,1212],[302,1212]],[[528,1062],[692,1062],[692,1202],[528,1202]]]}},
/* 📜 清・棋譜庫「文瀾閣」（同上，清・棋譜庫）。燈盞不登記，no 照原圖（含燈架）；回紋牙板比大案小，點牙板跳牙板 */
{re:/data\/libmap\/lib_qing\.webp/,D:{k:"lb_qing",nm:"清・文瀾閣",it:[
  {n:"露明屋架",nh:1,s:[[[0,0],[768,0],[768,190],[500,150],[0,150]]],
   t:"杭州的文瀾閣，是乾隆年間收藏《四庫全書》的江南三閣之一。抬頭看，斜屋頂的木架直接露出來，沒有天花板遮住。"},
  {n:"冰裂紋格扇窗",s:[[[520,222],[725,222],[725,358],[520,358]]],
   t:"二樓的窗是「冰裂紋」格扇窗，木條拼成像冰塊裂開的紋路。紋路看起來不規則，卻一格一格拼得很整齊。"},
  {n:"回紋牙板",s:[[[95,1258],[672,1250],[672,1298],[95,1302]]],
   t:"大畫案桌面底下那條橫板叫「牙板」。上面雕著回紋，一個個方形的迴旋花紋連成長長一串。"},
  {n:"畫案和函套",s:[[[64,1082],[300,1078],[300,1240],[50,1250]],[[50,1250],[722,1238],[716,1376],[64,1376]]],
   t:"案上和書櫥裡的書，都裝在布面的函套裡，平放疊起來。相傳《四庫全書》按經、史、子、集四部，書衣分成綠、紅、藍、灰四種顏色，一眼就分得出是哪一部；所以這一站右邊木櫥由上到下是綠、紅、藍，案上是灰。"},
  {n:"回紋欄杆",s:[[[0,560],[230,448],[460,440],[460,470],[240,500],[0,612]],[[548,470],[768,486],[768,580],[548,560]]],
   t:"二樓欄杆是一格一格的回紋：細木條一直轉直角，向內繞成方形的螺旋，一個接一個連成一串。大畫案的牙板上也雕著回紋，是清代家具、建築常見的花紋。"},
  {n:"鎮尺",s:[[[278,1112],[300,1115],[288,1205],[266,1202]],[[474,1110],[494,1110],[508,1196],[486,1198]]],
   t:"攤開的書兩邊，各壓著一根長條的「鎮尺」，把書頁壓平，是書桌上常見的文具。"}],
  no:[[[0,648],[215,648],[215,1088],[0,1088]],[[538,700],[768,700],[768,1032],[538,1032]],[[0,192],[502,192],[502,425],[0,425]],[[500,368],[768,368],[768,452],[500,452]],[[302,1108],[476,1108],[476,1212],[302,1212]],[[528,1062],[692,1062],[692,1202],[528,1202]],[[152,915],[228,915],[228,1168],[152,1168]]]}}
